import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { NavLink, Outlet, useLocation } from 'react-router-dom';
import { AuthUserPublic, CollegeOption, fetchCollegeOptions, fetchSchoolDashboard } from '../api';
import { SchoolSessionProvider } from './useSchoolSession';
import { SchoolPermissionsCard } from './SchoolPermissionsCard';
import { BrandSchoolChip } from '../components/BrandSchoolChip';
import './school.css';

interface SchoolAppProps {
  sessionUser: AuthUserPublic;
  onLogout: () => void;
}

const SchoolApp: React.FC<SchoolAppProps> = ({ sessionUser, onLogout }) => {
  const roleLabel = sessionUser.role === 'admin' ? '管理员' : '辅导员';
  const isAdmin = sessionUser.role === 'admin';
  const location = useLocation();
  const [pendingAlerts, setPendingAlerts] = useState(0);
  const [colleges, setColleges] = useState<CollegeOption[]>([]);

  const refreshPending = useCallback(() => {
    fetchSchoolDashboard()
      .then((d) => setPendingAlerts(d.pendingAlerts ?? 0))
      .catch(() => setPendingAlerts(0));
  }, []);

  useEffect(() => {
    refreshPending();
  }, [refreshPending, location.pathname]);

  useEffect(() => {
    const onAlertsUpdated = () => refreshPending();
    window.addEventListener('psyqa:alerts-updated', onAlertsUpdated);
    return () => window.removeEventListener('psyqa:alerts-updated', onAlertsUpdated);
  }, [refreshPending]);

  useEffect(() => {
    fetchCollegeOptions()
      .then((d) => setColleges(d.colleges))
      .catch(() => setColleges([]));
  }, []);

  const managedOrgNames = useMemo(() => {
    if (!sessionUser.managedOrgIds?.length) return [];
    return sessionUser.managedOrgIds.map(
      (id) => colleges.find((c) => c.id === id)?.name || id
    );
  }, [sessionUser.managedOrgIds, colleges]);

  const scopeLabel = useMemo(() => {
    if (sessionUser.role === 'admin') {
      return sessionUser.schoolName ? `数据范围：${sessionUser.schoolName}（全校）` : '数据范围：全校';
    }
    if (managedOrgNames.length > 0) {
      return `管辖院系：${managedOrgNames.join('、')}`;
    }
    if (sessionUser.orgName) {
      return `数据范围：${sessionUser.orgName}`;
    }
    return '数据范围：本院系';
  }, [sessionUser, managedOrgNames]);

  const userMetaParts = [
    sessionUser.schoolName,
    sessionUser.orgName && sessionUser.role === 'counselor' ? sessionUser.orgName : null,
    `@${sessionUser.username}`
  ].filter(Boolean);

  return (
    <SchoolSessionProvider value={{ sessionUser }}>
      <div className="school-app">
        <header className="school-header">
          <div className="school-brand">
            <span aria-hidden="true">🏫</span>
            <div>
              <BrandSchoolChip schoolName={sessionUser.schoolName} />
              <h1>心理港湾 · {isAdmin ? '管理端' : '辅导员端'}</h1>
              <p>院系心理态势看板 · 学生档案与对话管理</p>
            </div>
          </div>

          <div className="school-header-actions">
            {sessionUser.role === 'counselor' && (
              <span className="brand-school-chip brand-school-chip-scope" title="仅显示您管辖院系的数据">
                {scopeLabel}
              </span>
            )}
            {isAdmin && (
              <span className="brand-school-chip brand-school-chip-scope">全校数据</span>
            )}
            <div className="school-user-badge">
              <span className="school-user-avatar">{sessionUser.avatar}</span>
              <span className="school-user-text">
                <strong>{sessionUser.displayName}</strong>
                <small className="muted school-user-meta">
                  {roleLabel}
                  {userMetaParts.length > 0 ? ` · ${userMetaParts.join(' · ')}` : ''}
                </small>
              </span>
            </div>
            <button type="button" className="account-switch-btn" onClick={onLogout}>
              退出登录
            </button>
          </div>
        </header>

        <div className="school-body">
          <nav className="school-nav">
            <NavLink to="/school/dashboard" end className={({ isActive }) => (isActive ? 'active' : '')}>
              数据看板
            </NavLink>
            <NavLink to="/school/alerts" className={({ isActive }) => (isActive ? 'active' : '')}>
              风险告警
              {pendingAlerts > 0 && <span className="school-nav-badge">{pendingAlerts}</span>}
            </NavLink>
            <NavLink to="/school/students" className={({ isActive }) => (isActive ? 'active' : '')}>
              学生列表
            </NavLink>
            {isAdmin && (
              <>
                <NavLink to="/school/admin/users" className={({ isActive }) => (isActive ? 'active' : '')}>
                  用户管理
                </NavLink>
                <span className="school-nav-admin-badge">管理员</span>
              </>
            )}
          </nav>

          <main className="school-main">
            <SchoolPermissionsCard />
            <Outlet />
          </main>
        </div>
      </div>
    </SchoolSessionProvider>
  );
};

export default SchoolApp;
